"""The FFT configurations which are generated and verified by the CI.

The list below is the single source of truth for

* the RTL which is generated by ``fft.py``,
* the cocotb test modules (``test_fft_*.py``) and
* the verilator builds which are performed by ``conftest.py``.
"""

from __future__ import annotations

ARCHES = ("memory_based", "pipelined")
PIPELINE_STYLES = ("unrolled", "sdf", "sdc", "mdf")
TWIDDLE_MODES = ("rom", "cordic", "hybrid", "no_mem")
DATA_FORMATS = ("fixed", "block_float")
SCALINGS = ("stage", "none")
ORDERINGS = ("dit", "dif")
RADICES = ("2",)

_ARCH_TAG = {
    "memory_based": "Memory",
    "pipelined": "Pipelined",
}

_PIPELINE_TAG = {
    "sdf": "Sdf",
    "unrolled": "Unrolled",
    "sdc": "Sdc",
    "mdf": "Mdf",
}

_TWIDDLE_TAG = {
    "rom": "Rom",
    "cordic": "Cordic",
    "hybrid": "Hybrid",
    "no_mem": "NoMem",
}

_ORDERING_TAG = {
    "dit": "Dit",
    "dif": "Dif",
}


def fft_name(width: int, points: int, radices: str, eval_mode: str,
             pipeline_style: str, twiddle_mode: str, data_format: str,
             scaling: str, stages: int, inverse: bool, ordering: str,
             parallel: int) -> str:
    """The name of the generated SystemVerilog module."""
    name = f"Fft{_ARCH_TAG[eval_mode]}"
    if eval_mode == "pipelined":
        # the sub topology only exists for the pipelined architecture, naming
        # a memory based design after it would be misleading
        name += _PIPELINE_TAG[pipeline_style]
    name += (f"{_TWIDDLE_TAG[twiddle_mode]}{_ORDERING_TAG[ordering]}"
             f"R{radices}W{width}P{points}")
    if stages != 1:
        name += f"St{stages}"
    if data_format != "fixed":
        name += f"_{data_format}"
    if scaling != "stage":
        name += f"_{scaling}"
    if inverse:
        name += "Inv"
    if parallel != 1:
        name += f"P{parallel}"
    return name


def test_module_name(params: dict) -> str:
    """The name of the pytest/cocotb module which verifies a configuration."""
    name = f"pycde_example.test_fft_{params['eval_mode']}"
    if params["eval_mode"] == "pipelined":
        # the sub topology of the pipelined architecture
        name += f"_{params['pipeline_style']}"
    name += (f"_{params['ordering']}_r{params['radices']}"
             f"_w{params['width']}_p{params['points']}")
    if params["twiddle_mode"] != "rom":
        name += f"_{params['twiddle_mode']}"
    if params.get("stages", 1) != 1:
        name += f"_s{params['stages']}"
    if params["inverse"]:
        name += "_inv"
    return name


def _config(width: int, points: int, ordering: str = "dit",
            twiddle_mode: str = "rom", inverse: bool = False,
            data_format: str = "fixed", scaling: str = "stage",
            stages: int = 1, radices: str = "2",
            eval_mode: str = "memory_based",
            pipeline_style: str = "sdf", parallel: int = 1) -> dict:
    params = {
        "width": width,
        "points": points,
        "radices": radices,
        "eval_mode": eval_mode,
        "pipeline_style": pipeline_style,
        "twiddle_mode": twiddle_mode,
        "data_format": data_format,
        "scaling": scaling,
        "stages": stages,
        "inverse": inverse,
        "ordering": ordering,
        "parallel": parallel,
    }
    name = fft_name(**params)
    return {
        "params": params,
        "name": name,
        "test_module": test_module_name(params),
        # every configuration is built into its own system (a PyCDE system may
        # only have a single top level module)
        # the file is named after the class of the module
        "rtl": f"build/ip_fft_lib/{name}/hw/Fft.sv",
    }


FFT_CONFIGS: list[dict] = [
    # the iterative (memory based) architecture, both orderings
    _config(width=16, points=16, ordering="dit"),
    _config(width=16, points=16, ordering="dif"),
    # a different width and a different number of points
    _config(width=24, points=32, ordering="dit"),
    _config(width=16, points=8, ordering="dit"),
    _config(width=16, points=8, ordering="dif"),
    # the twiddle factors generated by a CORDIC
    _config(width=16, points=16, ordering="dit", twiddle_mode="cordic"),
    # the generator which keeps a table for a small transform and generates
    # the factors for a large one
    _config(width=16, points=16, ordering="dit", twiddle_mode="hybrid"),
    # the inverse transform
    _config(width=16, points=16, ordering="dit", inverse=True),
    # a small transform
    _config(width=16, points=4, ordering="dit"),
    # the pipelined (unrolled) architecture
    _config(width=16, points=8, ordering="dit", eval_mode="pipelined",
            pipeline_style="unrolled", stages=1),
    _config(width=16, points=8, ordering="dif", eval_mode="pipelined",
            pipeline_style="unrolled", stages=2),
    # the single path delay feedback architecture
    _config(width=16, points=8, ordering="dit", eval_mode="pipelined",
            pipeline_style="sdf", stages=1),
    _config(width=16, points=8, ordering="dif", eval_mode="pipelined",
            pipeline_style="sdf", stages=1),
    _config(width=16, points=16, ordering="dit", eval_mode="pipelined",
            pipeline_style="sdf", stages=2),
    # the single path delay commutator: a decimation in frequency pipeline
    # which reads the samples in the natural order
    _config(width=16, points=8, ordering="dif", eval_mode="pipelined",
            pipeline_style="sdc", stages=1),
    _config(width=16, points=16, ordering="dif", eval_mode="pipelined",
            pipeline_style="sdc", stages=1),
    # the smallest transform the commutator handles
    _config(width=16, points=2, ordering="dif", eval_mode="pipelined",
            pipeline_style="sdc", stages=1),
    # the multi path delay feedback: the first stage splits the frame and two
    # delay feedback chains transform the halves side by side
    _config(width=16, points=8, ordering="dif", eval_mode="pipelined",
            pipeline_style="mdf", stages=1),
    _config(width=16, points=16, ordering="dif", eval_mode="pipelined",
            pipeline_style="mdf", stages=1),
    # the smallest and the largest transform the feedback paths handle
    _config(width=16, points=4, ordering="dif", eval_mode="pipelined",
            pipeline_style="mdf", stages=1),
    _config(width=16, points=32, ordering="dif", eval_mode="pipelined",
            pipeline_style="mdf", stages=1),
    # the largest datapath which does not scale the stages: the transform does
    # not divide by the number of points then, so the width has to hold it
    _config(width=24, points=16, ordering="dif", scaling="none"),
]

#: The twiddle generator is tested on its own (as a top level module).
TWIDDLE_TEST = {
    "name": "TwiddleCordic16W16",
    "test_module": "pycde_example.test_fft_twiddle",
    "rtl": "build/ip_fft_twiddle/hw/Twiddle.sv",
}
